import{_ as t,o as r,c as a,a as i}from"./app.c1132791.js";const d=JSON.parse('{"title":"部署","description":"","frontmatter":{},"headers":[{"level":2,"title":"GitHub Pages","slug":"github-pages","link":"#github-pages","children":[]},{"level":2,"title":"Netlify","slug":"netlify","link":"#netlify","children":[]},{"level":2,"title":"Vercel","slug":"vercel","link":"#vercel","children":[]}],"relativePath":"zh/getting-started/deploy.md"}'),l={name:"zh/getting-started/deploy.md"};function n(s,e,o,p,h,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-hidden="true">#</a></h1><h2 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-hidden="true">#</a></h2><p>本項目配備了自動生成部署文件的 GitHub Actions 腳本，它會在您提交修改後運行再提交到 gh-pages 分支。</p><p>需要使用時，只需要設定 GitHub Pages 的部署分支為 gh-pages 既可。</p><blockquote><p>如果您提交修改後 GitHub Actions 腳本沒有自動運行，請檢查您的倉庫是否存在多餘的其他分支，您也可以手動運行腳本。</p></blockquote><h2 id="netlify" tabindex="-1">Netlify <a class="header-anchor" href="#netlify" aria-hidden="true">#</a></h2><p>本項目為 Netlify 配備了<a href="https://github.com/importantimport/urara/blob/main/netlify.toml" target="_blank" rel="noreferrer"><strong>構建配置文件</strong></a>，當導入項目時，無需填寫構建設定。</p><p>若要在 Netlify 上部署本項目，您需要擁有一個 Netlify 帳號，並在需要的倉庫中安裝 <a href="https://github.com/apps/netlify/installations/new" target="_blank" rel="noreferrer"><strong>Netlify app</strong></a> 後，既可訪問選中的倉庫。</p><p>接下來，只需要按照 <a href="https://app.netlify.com/start" target="_blank" rel="noreferrer"><strong>Import an existing project</strong></a> 頁面繼續操作既可完成部署過程。</p><h2 id="vercel" tabindex="-1">Vercel <a class="header-anchor" href="#vercel" aria-hidden="true">#</a></h2><p>要在 Vercel 上部署本項目，您需要擁有一個 Vercel 帳號，就可以開始<a href="https://vercel.com/new" target="_blank" rel="noreferrer"><strong>添加新項目</strong></a>。</p><p>您可以從公開 git 倉庫導入項目，若要導入 GitHub 私有倉庫，需關聯 GitHub 帳號進行授權。</p><p>選擇倉庫後，Vercel 會自動識別倉庫並選擇合適的架構，無需填寫構建與輸出設定。</p><p>您還可以根據需要添加其他設定，再進行部署，最後等待部署完成既可。</p>',14)])])}const f=t(l,[["render",n]]);export{d as __pageData,f as default};
